func collectAccountProject(rows *orm.Rows, keyFn func(*AccountProjectRow) orm.Key) *orm.Collection[AccountProjectRow] {
	c := orm.NewCollection[AccountProjectRow](len(rows.Data))
	for _, vals := range rows.Data {
		r := scanAccountProject(vals, rows.Assemble, rows)
		if keyFn != nil {
			c.Put(keyFn(r), r)
			continue
		}
		key, ok := orm.KeyFromRow(vals, rows.Assemble.Key)
		if !ok {
			panic("assembly collection key contains null")
		}
		c.Put(key, r)
	}
	return c
}

func collectAccountProjectDirect(rows []*AccountProjectRow, keyFn func(*AccountProjectRow) orm.Key) *orm.Collection[AccountProjectRow] {
	c := orm.NewCollection[AccountProjectRow](len(rows))
	for _, r := range rows {
		if keyFn != nil {
			c.Put(keyFn(r), r)
		} else {
			c.Put(orm.KeyFromValues([]any{r.AccountSeq, r.ProjectSeq}), r)
		}
	}
	return c
}

